/**
 * Initializes and creates an account corresponding to the specified accountProperties and registers the resulting ProtocolProvider in the <tt>context</tt> BundleContext parameter. This method has a persistent effect. Once created the resulting account will remain installed until removed through the uninstallAccount method.
 * @param accountProperties a set of protocol (or implementation) specificproperties defining the new account.
 * @return the AccountID of the newly loaded account
 */
public AccountID loadAccount(Map<String,String> accountProperties){
  AccountID accountID=createAccount(accountProperties);
  loadAccount(accountID);
  return accountID;
}
